///
/// This function will never spin-wait and will return immediately.
pub fn try_upread(&self) -> Option<RwLockUpgradeableGuard<'_, T, G>> {
    proof_decl!{
        let tracked mut upgrade_guard_token: Option<OneLeftOwner<HalfPerm<T>, NoPerm<T>, 3>> = None;
        let tracked mut retract_upgrade_token: Option<UniqueToken> = None;
    }
    proof!{
        use_type_invariant(self);
        lemma_consts_properties();
    }
    let guard = G::guard();
    // let lock = self.lock.fetch_or(UPGRADEABLE_READER, Acquire) & (WRITER | UPGRADEABLE_READER);
    let lock_value =
        atomic_with_ghost!(
        self.lock => fetch_or(UPGRADEABLE_READER);
        update prev -> next;
        ghost g => {
            // Try to take the upreader guard token
            if g.upreader_guard_token is Some {
                let tracked token = g.upreader_guard_token.tracked_take_some();
                upgrade_guard_token = Some(token);
            }

            // Try to take the retract token
            if g.upread_retract_token is Some {
                let tracked token = g.upread_retract_token.tracked_take_some();
                retract_upgrade_token = Some(token);
            }
        }
    )
        & (WRITER | UPGRADEABLE_READER);

    if lock_value == 0 {
        return Some(
            RwLockUpgradeableGuard {
                inner: self,
                guard,
                tracked_token: Tracked(upgrade_guard_token.tracked_unwrap()),
            },
        );
    } else if lock_value == WRITER {
        // self.lock.fetch_sub(UPGRADEABLE_READER, Release);
        atomic_with_ghost!(
            self.lock => fetch_sub(UPGRADEABLE_READER);
            update prev -> next;
            ghost g => {
                // Return the retract token since we failed
                if retract_upgrade_token is Some {
                    let tracked token = retract_upgrade_token.tracked_unwrap();
                    g.upread_retract_token = Option::Some(token);
                }
            }
        );
    }
    None
}

